<?php
use App\Core\Database as DB;
$total=(int)DB::val("SELECT COUNT(*) FROM attendance_records WHERE user_id=? AND attendance_for='student'",[$student]);$pages=max(1,(int)ceil($total/20));$page=max(1,min($pages,(int)($_GET['page']??1)));$offset=($page-1)*20;$rows=DB::all("SELECT attendance_date,status,remarks FROM attendance_records WHERE user_id=? AND attendance_for='student' ORDER BY attendance_date DESC,id DESC LIMIT 20 OFFSET $offset",[$student]);page_header('My Attendance'); ?>
<?php require APP_ROOT.'/app/Views/attendance_checkin.php'; ?>
<section class="card"><div class="table-wrap"><table><thead><tr><?php foreach(['Date','Status','Remarks'] as $label): ?><th><?= e(tr($label)) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e(fmt_date($r['attendance_date'])) ?></td><td><span class="pill <?= e($r['status']) ?>"><?= e(tr($r['status'])) ?></span></td><td><?= e($r['remarks']??'—') ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="3"><?= e(tr('No records yet')) ?></td></tr><?php endif; ?></tbody></table></div></section><div class="pagination"><span><?= $total ?> <?= e(tr('records')) ?></span><nav><?php if($page>1): ?><a class="btn" href="?page=<?= $page-1 ?>"><?= e(tr('Previous')) ?></a><?php endif; ?><?php if($page<$pages): ?><a class="btn" href="?page=<?= $page+1 ?>"><?= e(tr('Next')) ?></a><?php endif; ?></nav></div><?php page_footer();
